+        for (int a = 0; a < nf; a++) {
+            int i = freeIdx[a];
+            double[] ci = coef[i];
+            int ai = axis[i];
+            for (int b = a; b < nf; b++) {
+                int j = freeIdx[b];
+                double[] cj = coef[j];
+                int aj = axis[j];
+                boolean sameAxis = (ai == aj);
+                double sum = 0.0;
+                for (int t = 0; t < n; t++) {
+                    double cc = ci[t] * cj[t];
+                    if (cc == 0.0) continue;
+                    double gxx = gx[t], gzz = gz[t];
+                    double nrm = Math.sqrt(gxx * gxx + gzz * gzz + EPS2);
+                    double hi = (ai == 0 ? gxx : gzz) / nrm;
+                    double hj = (aj == 0 ? gxx : gzz) / nrm;
+                    sum += (mMag[t] / nrm) * cc * ((sameAxis ? 1.0 : 0.0) - hi * hj);
+                }
+                H[a][b] = sum;
+                H[b][a] = sum;
+            }
+        }
+    }
+
