+    private boolean choleskySolve(int nf, double damp) {
+        for (int a = 0; a < nf; a++) {
+            for (int b = 0; b <= a; b++) {
+                double s = H[a][b] + (a == b ? damp : 0.0);
+                for (int k = 0; k < b; k++) s -= Lwork[a][k] * Lwork[b][k];
