+                    if (s <= 0.0) return false;
+                    Lwork[a][a] = Math.sqrt(s);
+                } else {
+                    Lwork[a][b] = s / Lwork[b][b];
+                }
+            }
+            step[a] = -gradient[freeIdx[a]];
+        }
+        for (int a = 0; a < nf; a++) {
+            double s = step[a];
+            for (int k = 0; k < a; k++) s -= Lwork[a][k] * step[k];
+            step[a] = s / Lwork[a][a];
+        }
+        for (int a = nf - 1; a >= 0; a--) {
+            double s = step[a];
+            for (int k = a + 1; k < nf; k++) s -= Lwork[k][a] * step[k];
+            step[a] = s / Lwork[a][a];
+        }
+        return true;
+    }
+}

