+    @Test
+    public void closedFormSolvesAllFixtures() {
+        for (String fx : new String[]{"j121.json", "j154.json", "j1097.json"}) {
+            SaveFile file = SaveIO.parseSafe(readFixture(fx));
+            InputData inputs = new InputData();
